// State | Next state in=0, Next state in=1 | Output
// A | A, B | 0
// B | C, B | 0
// C | A, D | 0
// D | C, B | 1

module top_module (
	input in,
	input [3:0] state,
	output reg [3:0] next_state,
	output out
);

